#include "DashManifest.hpp"
#include "MediaPublication.hpp"
#include <iostream>
#include <sstream>
using namespace udm;
static Json checks=Json::array(),outputs=Json::array();
static void check(bool ok,const char* name){checks.push_back({{"passed",ok},{"name",name}});if(!ok)throw std::runtime_error(name);}
static Json frames(const fs::path& path,const Cancel& cancel){
 const auto text=execute(appDir()/L"tools/ffmpeg.exe",{L"-hide_banner",L"-loglevel",L"error",L"-xerror",L"-nostdin",L"-i",path.wstring(),L"-map",L"0:v:0",L"-f",L"framemd5",L"-"},30,cancel);Json result=Json::array();std::istringstream lines(text);std::string line;while(std::getline(lines,line))if(!line.empty()&&line[0]!='#'){auto comma=line.rfind(',');if(comma==std::string::npos)throw std::runtime_error("Invalid frame oracle output");result.push_back(trim(line.substr(comma+1)));}return result;
}
int wmain(int argc,wchar_t** argv){
 if(argc!=4)return 2;const auto root=fs::absolute(argv[1]),destination=fs::absolute(argv[3]);if(fs::exists(root)||fs::exists(destination))return 2;fs::create_directories(root);WSADATA winsock{};WSAStartup(MAKEWORD(2,2),&winsock);CoInitializeEx(nullptr,COINIT_MULTITHREADED);std::string error;
 try{auto cancel=std::make_shared<Cancel>();Json prefs=Json::object();const auto snapshot=refreshDashManifest(utf8(argv[2]),{},prefs,cancel);std::vector<DashSelectedTrack> tracks;
 for(size_t n=0;n<snapshot.manifest.nodes.size();++n)if(snapshot.manifest.nodes[n].name=="Representation")tracks.push_back(selectDashTrack(snapshot,n,*cancel));check(tracks.size()==2,"Owned manifest selects two distinct Period tracks");
 const auto capture=[&](const fs::path& folder,size_t period){DashLiveUpdate update;update.state.snapshot=snapshot;update.state.tracks.push_back(tracks[period]);update.staticPresentation=true;auto address=tracks[period].addressing;update.windows.push_back(planDashTemplateWindow(address,0,1000,*cancel));auto index=captureDashWindow(folder,update,{},prefs,cancel,{},DashCaptureInterval{0,1},1);index=sealDashRecording(folder,*cancel);check(yes(index,"sealed")&&real(index,"captureStart")==0&&real(index,"captureEnd")==1,"Real segment resources are captured and sealed for a complete Period");};
 capture(root/L"single",0);capture(root/L"session",0);capture(root/L"session/period-0001",1);atomicText(root/L"capture-complete.json","{}",false);
 const auto deadline=GetTickCount64()+15000;while(!fs::exists(root/L"offline.ready")){if(GetTickCount64()>deadline)throw std::runtime_error("Origin shutdown handshake timed out");cancel->wait(20);}check(true,"Origin is stopped before assembly, reuse and publication");
 const auto publish=[&](DashRecordingOutput& output,const char* label,const std::string& expectedHash,i64 expectedSize){Manager manager(root/(wide(label)+L"-catalog"));auto settings=manager.state["Settings"];settings["CategoryFolders"]=false;settings["DownloadFolder"]=utf8((destination/wide(label)).wstring());manager.setSettings(settings);auto job=manager.add("https://example.invalid/owned-dash.mp4","","recording.mp4","Main queue",true);check(bool(output.verifiedSource),"Actual assembly retains ownership of the verified file");auto pin=output.verifiedSource->clone();output.verifiedSource.reset();check(bool(pin),"Actual verified source transfers into publication");publishMediaOutput(manager,job,output.staging,output.sha256,cancel,nullptr,std::move(pin));manager.stop();check(str(job->data,"Status")=="Complete"&&fileHash(job->target())==expectedHash,"Actual final file and accepted history match the pre-publication checksum");check((i64)fs::file_size(job->target())==expectedSize,"Exact assembled size before publication equals final file size");auto decoded=frames(job->target(),*cancel);check(!decoded.empty(),"Published DASH media decodes completely through EOF");outputs.push_back({{"case",label},{"prePublicationBytes",expectedSize},{"finalBytes",(i64)fs::file_size(job->target())},{"sha256",expectedHash},{"frames",decoded}});};
 auto single=assembleDashRecording(root/L"single",*cancel);check(!single.reused&&single.duration==1,"First real single-Period output is assembled with complete duration");const auto singleHash=single.sha256;const auto singleSize=single.bytes;const auto singleName=single.staging;single.verifiedSource.reset();auto reused=assembleDashRecording(root/L"single",*cancel);check(reused.reused&&reused.staging==singleName&&reused.sha256==singleHash,"Single-Period cached output is reused without another mux");publish(reused,"single",singleHash,singleSize);
 Json selection={{"audioOnly",false},{"audioExpected",false},{"container","mp4"},{"height",360},{"tracks",Json::array({{{"kind","video"},{"periodId","p0"},{"adaptationId","v"},{"representationId","r"}}})}};
 auto joined=assembleDashRecordingSession(root/L"session",{".","period-0001"},selection,*cancel);check(!joined.reused&&joined.duration==2,"Two adjacent real Periods assemble into the full two-second output");const auto joinedHash=joined.sha256;const auto joinedSize=joined.bytes;const auto joinedName=joined.staging;joined.verifiedSource.reset();auto cached=assembleDashRecordingSession(root/L"session",{".","period-0001"},selection,*cancel);check(cached.reused&&cached.staging==joinedName&&cached.sha256==joinedHash,"Joined session cache reuses the identical completed file");publish(cached,"joined",joinedHash,joinedSize);
 }catch(const std::exception& e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"checks",checks},{"outputs",outputs}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<error<<"\n";CoUninitialize();WSACleanup();return error.empty()?0:1;
}
